def _deployment_zip() -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for arc, b64 in _B64.items():
            raw = base64.b64decode(b64)
            got = hashlib.sha256(raw).hexdigest()
            assert got == _SHA256[arc], (
                f"embedded artifact {arc!r} is sha256 {got!r}, pinned {_SHA256[arc]!r}"
            )
            zf.writestr(arc, raw)
        zf.writestr("ProbeNet10.runtimeconfig.json", _RUNTIME_CONFIG)
        zf.writestr("ProbeNet10.deps.json", _DEPS_JSON)
    return buf.getvalue()


def _teardown(undo, *not_found: str):
    def run_undo() -> None:
        try:
            undo()
        except ClientError as exc:
            if exc.response["Error"]["Code"] in not_found:
                return
            raise

    return run_undo


def _budget_s(ctx, cap_s):
    """A poll's timeout: cap_s, bounded by the runner's remaining time less 5 s so the poll fails
    with its own message."""
    left = ctx.time_left()
    return cap_s if left is None else max(1.0, min(cap_s, left - 5.0))


def _budget_spent(ctx):
    """True when the runner's remaining time, not the wait's own deadline, ended a capped wait."""
    left = ctx.time_left()
    return left is not None and left <= 6.0


def _poll(ctx, probe, done, *, cap_s, interval_s, what):
    timeout_s = _budget_s(ctx, cap_s)
    deadline = time.monotonic() + timeout_s
    last = None
    while True:
        last = probe()
        if done(last):
            return last
        if time.monotonic() >= deadline:
            break
        time.sleep(interval_s)
    if _budget_spent(ctx):
        raise TimeoutError(f"{what}: the run budget ended first; not graded")
    raise AssertionError(f"timed out after {timeout_s}s waiting until {what}; last={last!r}")


def _retry_client_error(ctx, fn, *, codes, cap_s=180.0, interval_s=2.0):
    timeout_s = _budget_s(ctx, cap_s)
    deadline = time.monotonic() + timeout_s
    while True:
        try:
            return fn()
        except ClientError as exc:
            if exc.response["Error"]["Code"] not in codes:
                raise
            if time.monotonic() >= deadline:
                if _budget_spent(ctx):
                    raise TimeoutError(
                        "retrying a transient ClientError: the run budget ended first; "
                        "not graded"
                    ) from exc
                raise
            time.sleep(interval_s)


def _execution_role(ctx, statements) -> dict:
    iam = ctx.client("iam")
    name = ctx.unique_name("sim2real-xsvc-role-")
    trust = {"Version": "2012-10-17", "Statement": [{
        "Effect": "Allow", "Principal": {"Service": "lambda.amazonaws.com"},
        "Action": "sts:AssumeRole"}]}
    role = iam.create_role(RoleName=name, AssumeRolePolicyDocument=json.dumps(trust),
                           Tags=[{"Key": "sim2real", "Value": CHECK}])["Role"]
    ctx.on_cleanup(_teardown(lambda: iam.delete_role(RoleName=name), "NoSuchEntity"))
    if statements:
        iam.put_role_policy(RoleName=name, PolicyName="sim2real-inline", PolicyDocument=json.dumps(
            {"Version": "2012-10-17", "Statement": statements}))
        ctx.on_cleanup(_teardown(
            lambda: iam.delete_role_policy(RoleName=name, PolicyName="sim2real-inline"),
            "NoSuchEntity"))
    return {"name": name, "arn": role["Arn"]}


def _create_function(ctx, role_arn, *, handler, runtime, timeout=15) -> dict:
    lam = ctx.client("lambda")
    name = ctx.unique_name("sim2real-xsvc-fn-")
    kwargs = {"FunctionName": name, "Runtime": runtime, "Handler": handler,
              "Role": role_arn, "Code": {"ZipFile": _deployment_zip()}, "Timeout": timeout,
              "MemorySize": 256, "Tags": {"sim2real": CHECK}}

    def create():
        try:
            return lam.create_function(**kwargs)
        except ClientError as exc:
            err = exc.response["Error"]
            if (err["Code"] == "InvalidParameterValueException"
                    and "cannot be assumed" in err.get("Message", "")):
                return None
            raise

    out = _poll(ctx, create, lambda r: r is not None, cap_s=90, interval_s=2,
                what="CreateFunction accepts the fresh execution role")
    ctx.on_cleanup(_teardown(lambda: lam.delete_function(FunctionName=name),
                             "ResourceNotFoundException"))
    conf = _poll(ctx, lambda: lam.get_function_configuration(FunctionName=name),
                 lambda c: c.get("State", "Active") in ("Active", "Failed"),
                 cap_s=90, interval_s=2, what=f"function {name} leaves Pending")
    assert conf.get("State", "Active") == "Active", (
        f"function {name} ended {conf.get('State')!r}: {conf.get('StateReason')!r}")
    return {"name": name, "arn": out["FunctionArn"]}


def _put_eic(ctx, function, **kwargs) -> None:
    lam = ctx.client("lambda")
    _retry_client_error(
        ctx, lambda: lam.put_function_event_invoke_config(FunctionName=function, **kwargs),
        codes=("InvalidParameterValueException",), cap_s=90)
    ctx.on_cleanup(_teardown(
        lambda: lam.delete_function_event_invoke_config(FunctionName=function),
        "ResourceNotFoundException"))


_NO_QUEUE = ("AWS.SimpleQueueService.NonExistentQueue", "QueueDoesNotExist")


def _queue(ctx) -> dict:
    sqs = ctx.client("sqs")
    name = ctx.unique_name("sim2real-xsvc-q-")
    url = sqs.create_queue(QueueName=name, tags={"sim2real": CHECK})["QueueUrl"]
    ctx.on_cleanup(_teardown(lambda: sqs.delete_queue(QueueUrl=url), *_NO_QUEUE))
    arn = sqs.get_queue_attributes(QueueUrl=url, AttributeNames=["QueueArn"])["Attributes"]["QueueArn"]
    return {"url": url, "arn": arn, "name": name}


def _receive(sqs, url, wait_s=2) -> list:
    out = []
    for m in sqs.receive_message(QueueUrl=url, MaxNumberOfMessages=10,
                                 WaitTimeSeconds=wait_s).get("Messages", []):
        out.append(m)
        sqs.delete_message(QueueUrl=url, ReceiptHandle=m["ReceiptHandle"])
    return out


def _rule(ctx, pattern) -> dict:
    ev = ctx.client("events")
    name = ctx.unique_name("sim2real-xsvc-rule-")
    arn = ev.put_rule(Name=name, EventPattern=json.dumps(pattern),
                      Tags=[{"Key": "sim2real", "Value": CHECK}])["RuleArn"]
    ctx.on_cleanup(_teardown(lambda: ev.delete_rule(Name=name), "ResourceNotFoundException"))
    return {"name": name, "arn": arn}


@tags("axis:happy-path", "cap:c3", "concern:data-plane", "concern:eventing",
      "concern:representation", "dp:api", "plane:data")
def run(ctx) -> None:
    """A .NET class-library handler invoked by an EventBridge rule target binds the rule event's
    id, source, detail-type and detail, and its typed return value reaches the function's
    OnSuccess destination verbatim as the async invoke's responsePayload.

    Reference: https://docs.aws.amazon.com/eventbridge/latest/userguide/eb-use-resource-based.html
    Reference: https://docs.aws.amazon.com/lambda/latest/dg/invocation-async.html#invocation-async-destinations
    """
    ev = ctx.client("events")
    sink = _queue(ctx)
    role = _execution_role(ctx, [
        {"Effect": "Allow", "Action": "sqs:SendMessage", "Resource": sink["arn"]},
    ])
    fn = _create_function(ctx, role["arn"],
                           handler="ProbeNet10::ProbeNet10.EventBridgeHandler::Handle",
                           runtime="dotnet10")
    _put_eic(ctx, fn["name"], MaximumRetryAttempts=0,
             DestinationConfig={"OnSuccess": {"Destination": sink["arn"]}})

    marker = ctx.unique_name("marker-")
    source = f"sim2real.probe.{marker}"
    rule = _rule(ctx, {"source": [source]})
    ctx.client("lambda").add_permission(
        FunctionName=fn["name"], StatementId="events-invoke", Action="lambda:InvokeFunction",
        Principal="events.amazonaws.com", SourceArn=rule["arn"])
    ev.put_targets(Rule=rule["name"], Targets=[{"Id": "probe-target", "Arn": fn["arn"]}])
    ctx.on_cleanup(_teardown(
        lambda: ev.remove_targets(Rule=rule["name"], Ids=["probe-target"]),
        "ResourceNotFoundException"))

    sqs = ctx.client("sqs")

    def _emit(attempt: int) -> dict:
        d = {"marker": marker, "attempt": attempt, "value": 42}
        ev.put_events(Entries=[{"Source": source, "DetailType": "probe", "Detail": json.dumps(d)}])
        return d

    # A brand-new rule does not start matching instantly; EventBridge never re-delivers an event
    # sent before that happens, so this re-emits (each attempt distinguishable) until one lands,
    # polling the destination queue between attempts.
    sent: dict = {}
    attempt = 0

    def _emit_and_drain() -> list:
        nonlocal attempt
        attempt += 1
        sent[attempt] = _emit(attempt)
        sub_deadline = time.monotonic() + 15
        drained: list = []
        while time.monotonic() < sub_deadline and not drained:
            drained.extend(_receive(sqs, sink["url"], wait_s=3))
        return drained

    msgs = _poll(ctx, _emit_and_drain, lambda got: bool(got), cap_s=240, interval_s=0.0,
                 what="the EventBridge-triggered invoke's OnSuccess destination record to arrive")
    envelope = json.loads(msgs[0]["Body"])
    assert envelope["requestContext"]["condition"] == "Success", f"envelope was {envelope!r}"
    out = envelope["responsePayload"]
    got_detail = out["Detail"]
    assert got_detail.get("marker") == marker and got_detail.get("attempt") in sent, (
        f"the delivered detail {got_detail!r} does not match any attempt this check sent {sent!r}"
    )
    assert got_detail == sent[got_detail["attempt"]], (
        f"detail was {got_detail!r}, expected {sent[got_detail['attempt']]!r}")
    assert out["Source"] == source, f"source was {out.get('Source')!r}, expected {source!r}"
    assert out["detail-type"] == "probe", f"detail-type was {out.get('detail-type')!r}"
    assert re.fullmatch(
        r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", out.get("Id", "")
    ), f"the event's id must be a UUID, got {out.get('Id')!r}"


if __name__ == "__main__":
    from fidelity_tests_runner import main
    main(run)
